class Solution(object):
    def maxDistToClosest(self, seats):
        """
        :type seats: List[int]
        :rtype: int
        """
        n = len(seats)
        ans = 0
        for p1 in range(n):
            if seats[p1] == 1:
                ans = max(ans, p1)
                break
        for p2 in range(n - 1, -1, -1):
            if seats[p2] == 1:
                ans = max(ans, n - 1 - p2)
                break
        for p in range(p1 + 1, n):
            if seats[p] == 1:
                ans = max(ans, (p - p1) // 2)
                p1 = p
        return ans
